// path: apps/web/src/components/shell/AppShell.tsx
"use client";

import ThemeToggle from "@/components/common/ThemeToggle";
import LanguageToggle from "@/components/common/LanguageToggle";
import { useAuth } from "@/hooks/useAuth";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { ReactNode, useMemo } from "react";
import { useTranslation } from "react-i18next";

const navItems = [
  { key: "dashboard", href: "/dashboard" },
  { key: "planner", href: "/planner" },
  { key: "study", href: "/study" },
  { key: "timetable", href: "/timetable" },
  { key: "transcript", href: "/transcript" },
  { key: "warnings", href: "/warnings" },
  { key: "reminders", href: "/reminders" },
  { key: "settings", href: "/settings" },
] as const;

export default function AppShell({ children }: { children: ReactNode }) {
  const pathname = usePathname();
  const router = useRouter();
  const { t } = useTranslation();
  const { user, logout, loading } = useAuth();

  const currentLabel = useMemo(() => {
    const found = navItems.find((n) => n.href === pathname);
    return found ? t(`nav.${found.key}`) : "";
  }, [pathname, t]);

  const onLogout = async () => {
    await logout();
    router.push("/login");
  };

  return (
    <div className="min-h-screen bg-[var(--bg-main)] text-[var(--text-main)] transition-colors duration-300">
      <div className="flex min-h-screen">
        <aside className="hidden md:flex w-64 flex-col border-r border-[var(--border-main)] bg-[var(--bg-card)] px-4 py-5 backdrop-blur-xl">
          <div className="mb-6">
            <div className="text-2xl font-bold tracking-tight">MYDTU Assistant</div>
            <div className="mt-1 text-xs text-[var(--text-muted)]">
              Hệ thống trợ lý học tập DTU
            </div>
          </div>

          <nav className="flex flex-col gap-2">
            {navItems.map((item) => {
              const active = pathname === item.href;

              return (
                <Link
                  key={item.href}
                  href={item.href}
                  className={`rounded-2xl px-3 py-2.5 text-sm font-medium transition ${
                    active
                      ? "bg-[var(--accent)] text-white shadow-lg"
                      : "text-[var(--text-main)] hover:bg-[var(--bg-soft)]"
                  }`}
                >
                  {t(`nav.${item.key}`)}
                </Link>
              );
            })}
          </nav>
        </aside>

        <div className="flex min-w-0 flex-1 flex-col">
          <header className="sticky top-0 z-20 border-b border-[var(--border-main)] bg-[var(--bg-card)]/90 px-4 py-4 backdrop-blur-xl md:px-6">
            <div className="flex items-center justify-between gap-3">
              <div className="text-sm font-medium text-[var(--text-soft)]">
                {currentLabel}
              </div>

              <div className="flex items-center gap-2">
                <LanguageToggle />
                <ThemeToggle />
                {!loading && user ? (
                  <button
                    onClick={onLogout}
                    className="app-btn rounded-xl px-4 py-2 text-sm font-medium"
                    type="button"
                  >
                    {t("auth.logout")}
                  </button>
                ) : (
                  <Link
                    href="/login"
                    className="app-btn-primary rounded-xl px-4 py-2 text-sm font-medium"
                  >
                    {t("auth.login")}
                  </Link>
                )}
              </div>
            </div>
          </header>

          <main className="flex-1 p-4 md:p-6">{children}</main>
        </div>
      </div>
    </div>
  );
}